import {execFileSync} from 'node:child_process';import {stat,readFile,writeFile} from 'node:fs/promises';
const files=[...new Set(execFileSync('git',['ls-files','--modified','--others','--exclude-standard','-z']).toString().split('\0').filter(Boolean))];const findings=[];let bytes=0;let count=0;const largest=[];
const pattern=/(?:sk-(?:proj-|or-v1-)?[A-Za-z0-9_-]{24,}|gh[pousr]_[A-Za-z0-9]{30,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|Bearer\s+[A-Za-z0-9_.-]{24,})/g;
for(const p of files){const s=await stat(p);if(!s.isFile())continue;bytes+=s.size;count++;largest.push({path:p,bytes:s.size});if(s.size>8e6)continue;const b=await readFile(p);if(b.includes(0))continue;const text=b.toString();if(pattern.test(text))findings.push({path:p,type:'credential-pattern'});pattern.lastIndex=0;}
const report={files:count,bytes,findings,largest:largest.sort((a,b)=>b.bytes-a.bytes).slice(0,8)};await writeFile('.local/seven-smart-2026-10-20/final-secret-scan.json',JSON.stringify(report,null,2));console.log(report);
